// 单文件程序：由 rustc --edition 2021 直接编译，不经过 cargo。
// 输出固定，不依赖任何环境探测。

fn toolchain_roles() -> [(&'static str, &'static str); 3] {
    [
        ("rustup", "下载并切换工具链、目标与组件"),
        ("rustc", "把单个 crate 根编译成目标产物"),
        ("cargo", "读取 Cargo.toml，调度 rustc 完成构建"),
    ]
}

fn main() {
    println!("Rust 工具链三层职责:");
    for (i, (tool, role)) in toolchain_roles().iter().enumerate() {
        println!("{}. {:<7} -> {}", i + 1, tool, role);
    }
    println!("调用链: rustup 安装 -> cargo 编排 -> rustc 编译");
}

// 最小可执行程序：main 是入口，println! 是标准库宏。

fn greeting(name: &str) -> String {
    format!("你好，{}！", name)
}

fn main() {
    let message = greeting("Rustacean");
    println!("{}", message);
    println!("字符数 = {}", message.chars().count());
}

// 用单文件方式解析一个最小 Cargo.toml 的关键字段，
// 把清单结构变成可观察输出（无需真实 manifest 也能运行）。

#[derive(Debug)]
struct Manifest {
    name: &'static str,
    version: &'static str,
    edition: &'static str,
}

fn main() {
    let manifest = Manifest {
        name: "hello_qfli",
        version: "0.1.0",
        edition: "2021",
    };
    println!("[package]");
    println!("name = {:?}", manifest.name);
    println!("version = {:?}", manifest.version);
    println!("edition = {:?}", manifest.edition);
    println!("目录职责: Cargo.toml=清单, src/=源码, target/=可再生成的构建产物");
}

// 用一个小函数演示 check/build 的共同检查对象：类型与借用。
// 代码被设计成 clippy 友好（无多余 clone、无不必要分配）。

fn sum_even(numbers: &[i32]) -> i32 {
    numbers.iter().filter(|n| *n % 2 == 0).sum()
}

fn describe(stage: &str, note: &str) {
    println!("{:<18} {}", stage, note);
}

fn main() {
    describe("cargo check", "只做类型/借用检查，最快");
    describe("cargo build", "生成 target/debug 可执行文件");
    describe("cargo clippy", "追加静态建议 lint");
    describe("cargo fmt", "统一格式，不改语义");
    let data = [1, 2, 3, 4, 5, 6];
    println!("偶数之和 = {}", sum_even(&data));
}

// 单文件演示：不同“优化档位”影响的维度。
// 真实开关写在下方 Cargo 项目的 Cargo.toml 里。

fn knobs() -> [(&'static str, &'static str, &'static str); 4] {
    [
        ("opt-level", "0/1/2/3/s/z", "越高越快，s/z 偏向小体积"),
        ("lto", "false/true/thin", "链接时优化，编译更慢"),
        ("codegen-units", "1..256", "越少越利于优化"),
        ("panic", "unwind/abort", "abort 更小但不可恢复"),
    ]
}

fn main() {
    println!("release profile 关键开关:");
    for (name, values, effect) in knobs() {
        println!("- {:<14} {:<14} {}", name, values, effect);
    }
    let mut sum: u64 = 0;
    for i in 1..=1000u64 {
        sum += i;
    }
    println!("固定计算 sum(1..=1000) = {}", sum);
}

