// 单文件“版本范围判定器”：把 Cargo 的 ^ 语义变成可运行逻辑。
// Cargo 的 `^` 兼容规则（关键：0.x 与 0.0.x 的 breaking 组件不同）：
//   ^1.2.3 -> >=1.2.3, <2.0.0   （major>0：major 是不兼容位）
//   ^0.2.3 -> >=0.2.3, <0.3.0   （major==0：minor 是不兼容位）
//   ^0.0.3 -> >=0.0.3, <0.0.4   （major==0,minor==0：patch 是不兼容位）
// 所以不能只比较“主版本相等 + 不低于最小版本”。

fn parse(s: &str) -> (u64, u64, u64) {
    let mut it = s.split('.').map(|p| p.parse::<u64>().unwrap_or(0));
    (it.next().unwrap_or(0), it.next().unwrap_or(0), it.next().unwrap_or(0))
}

fn caret_upper_bound(req: (u64, u64, u64)) -> (u64, u64, u64) {
    let (maj, min, pat) = req;
    if maj > 0 {
        (maj + 1, 0, 0)
    } else if min > 0 {
        (0, min + 1, 0)
    } else {
        (0, 0, pat + 1)
    }
}

fn caret_allows(req: &str, candidate: &str) -> bool {
    let r = parse(req);
    let c = parse(candidate);
    let upper = caret_upper_bound(r);
    c >= r && c < upper
}

fn main() {
    for (req, candidates) in [
        ("1.2.3", ["1.2.3", "1.9.0", "2.0.0", "1.2.2"]),
        ("0.2.3", ["0.2.3", "0.2.9", "0.3.0", "0.2.2"]),
        ("0.0.3", ["0.0.3", "0.0.4", "0.0.2", "0.1.0"]),
    ] {
        for cand in candidates {
            println!("^{} 允许 {} -> {}", req, cand, caret_allows(req, cand));
        }
    }
}

