// 单文件版本：演示“库逻辑 + 二进制入口”的分层语义。
// 真实 workspace 的清单见下方 files 映射。

mod mathlib {
    pub fn gcd(mut a: u64, mut b: u64) -> u64 {
        while b != 0 {
            let t = a % b;
            a = b;
            b = t;
        }
        a
    }

    pub fn lcm(a: u64, b: u64) -> u64 {
        if a == 0 || b == 0 { 0 } else { a / gcd(a, b) * b }
    }
}

fn main() {
    println!("gcd(48, 18)  = {}", mathlib::gcd(48, 18));
    println!("lcm(4, 6)    = {}", mathlib::lcm(4, 6));
    println!("分层: lib 放纯逻辑, bin 只做输入输出");
}

