// 文档注释演示：/// 描述函数，main 里复用同一逻辑验证输出。
// 在真实库 crate 中，下方注释会渲染进 cargo doc 并作为 doctest 运行。

/// 返回 `value` 落在闭区间 `[low, high]` 内时的比例位置（0.0..=1.0）。
///
/// # Examples
///
/// ```
/// assert_eq!(position(5, 0, 10), 0.5);
/// ```
fn position(value: i32, low: i32, high: i32) -> f64 {
    if high == low {
        return 0.0;
    }
    (value - low) as f64 / (high - low) as f64
}

fn main() {
    println!("position(5, 0, 10) = {}", position(5, 0, 10));
    println!("position(0, 0, 10) = {}", position(0, 0, 10));
    println!("文档内代码块会被 cargo test 当作 doctest 运行");
}

// 本程序演示三类常见报错的“正确版本”：
//   E0382 使用已移动的值 -> 改为借用
//   E0502 可变与不可变借用冲突 -> 先取值再可变操作
//   E0308 类型不匹配 -> 显式转换

fn sum_len(words: &[String]) -> usize {
    words.iter().map(|w| w.len()).sum()
}

fn main() {
    let words = vec![String::from("rust"), String::from("ownership")];
    // E0382 修复：传引用而非移动
    println!("total_len = {}", sum_len(&words));

    // E0502 修复：先取出长度，结束不可变借用后再可变操作
    let first_len = words[0].len();
    let mut counts = vec![first_len];
    counts.push(words[1].len());
    println!("counts = {:?}", counts);

    // E0308 修复：显式 as 转换
    let ratio = counts[1] as f64 / counts[0] as f64;
    println!("ratio = {:.2}", ratio);
}

// 单文件版：把单元测试和可运行输出放在一起。
// 真实项目里集成测试位于 tests/ 目录（见 files 映射）。

fn digits_sum(text: &str) -> Option<u32> {
    let mut sum = 0u32;
    let mut seen = false;
    for c in text.chars() {
        if let Some(d) = c.to_digit(10) {
            sum += d;
            seen = true;
        }
    }
    if seen { Some(sum) } else { None }
}

fn main() {
    println!("digits_sum(\"a1b2c3\") = {:?}", digits_sum("a1b2c3"));
    println!("digits_sum(\"abc\")    = {:?}", digits_sum("abc"));
    println!("cargo test 会同时跑单元/集成/文档测试");
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn sums_all_digits() {
        assert_eq!(digits_sum("a1b2c3"), Some(6));
    }

    #[test]
    fn returns_none_without_digits() {
        assert_eq!(digits_sum("abc"), None);
    }
}

