// 两个输入都需要活得足够久，返回其一
fn longer<'a>(x: &'a str, y: &'a str) -> &'a str {
    if x.len() >= y.len() { x } else { y }
}

// 返回只依赖 x，y 可以更短命
fn prefixed<'a>(x: &'a str, prefix: &str) -> &'a str {
    let _ = prefix;
    x
}

fn main() {
    let a = String::from("long string here");
    let b = String::from("short");
    println!("longer = {}", longer(&a, &b));

    let owned = String::from("body");
    {
        let prefix = String::from("pre-");
        println!("prefixed = {}", prefixed(&owned, &prefix));
    }
    println!("owned 仍然有效: {}", owned);
}

