fn fill_and_sum(values: &mut Vec<i32>, n: i32) -> i32 {
    // 重新借用：values 仍是同一个 &mut，push 时自动 reborrow
    for i in 1..=n {
        values.push(i);
    }
    values.iter().sum()
}

fn swap_ends(values: &mut [i32]) {
    // split_at_mut 得到两个不重叠的可变借用
    if values.len() >= 2 {
        let mid = values.len() / 2;
        let (left, right) = values.split_at_mut(mid);
        std::mem::swap(&mut left[0], &mut right[right.len() - 1]);
    }
}

fn main() {
    let mut data = Vec::new();
    let sum = fill_and_sum(&mut data, 5);
    println!("sum = {}, data = {:?}", sum, data);

    swap_ends(&mut data);
    println!("after swap_ends = {:?}", data);
}

fn normalize(values: &mut [f64]) {
    let max = values.iter().copied().fold(f64::MIN, f64::max);
    if max == 0.0 {
        return;
    }
    // 先读取 max（不可变借用结束），再可变借用整体
    for v in values.iter_mut() {
        *v /= max;
    }
}

fn dedup_keep_order(values: &mut Vec<i32>) {
    let mut seen = std::collections::HashSet::new();
    values.retain(|v| seen.insert(*v));
}

fn main() {
    let mut data = [2.0, 4.0, 8.0];
    normalize(&mut data);
    println!("normalized = {:?}", data);

    let mut numbers = vec![1, 2, 1, 3, 2, 4];
    dedup_keep_order(&mut numbers);
    println!("deduped = {:?}", numbers);
}

fn swap_two(values: &mut [i32], i: usize, j: usize) {
    if i == j || i >= values.len() || j >= values.len() {
        return;
    }
    if i < j {
        let (left, right) = values.split_at_mut(j);
        std::mem::swap(&mut left[i], &mut right[0]);
    } else {
        let (left, right) = values.split_at_mut(i);
        std::mem::swap(&mut left[j], &mut right[0]);
    }
}

fn pairwise_double(values: &mut Vec<i32>) {
    // 用 zip 把相邻两个不重叠的可变引用配成对
    let mut it = values.iter_mut();
    while let (Some(a), Some(b)) = (it.next(), it.next()) {
        *a *= 2;
        *b *= 2;
    }
}

fn main() {
    let mut data = [1, 2, 3, 4, 5];
    swap_two(&mut data, 0, 4);
    println!("swapped = {:?}", data);

    let mut nums = vec![1, 2, 3, 4, 5];
    pairwise_double(&mut nums);
    println!("doubled = {:?}", nums);
}

// 错误示范（不可编译）: fn bad() -> &str { &String::from("x") }
// 修复 1: 返回拥有型
fn owned_upper(text: &str) -> String {
    text.to_uppercase()
}

// 修复 2: 把输出生命周期绑定到入参。
// 注意：这里按**字符**而不是字节取尾部，避免在多字节 UTF-8（如中文）上 panic。
fn tail<'a>(text: &'a str, n: usize) -> &'a str {
    let count = text.chars().count();
    if n >= count {
        return text;
    }
    let cut = count - n;
    // char_indices 给出每个字符的字节边界，切点必然落在边界上
    let byte_idx = text.char_indices().nth(cut).map(|(i, _)| i).unwrap_or(text.len());
    &text[byte_idx..]
}

// 修复 3: 结构体改为持有索引而非引用（避免自引用）
struct LineIndex {
    offsets: Vec<usize>,
}

impl LineIndex {
    fn build(text: &str) -> Self {
        let mut offsets = vec![0];
        for (i, b) in text.bytes().enumerate() {
            if b == b'\n' {
                offsets.push(i + 1);
            }
        }
        LineIndex { offsets }
    }

    fn line<'a>(&self, text: &'a str, idx: usize) -> Option<&'a str> {
        let start = *self.offsets.get(idx)?;
        let end = self.offsets.get(idx + 1).copied().unwrap_or(text.len());
        Some(&text[start..end].trim_end_matches('\n'))
    }
}

fn main() {
    println!("owned_upper = {}", owned_upper("abc"));
    println!("tail = {}", tail("abcdef", 3));
    println!("tail(cn) = {}", tail("你好世界", 2));

    let doc = "alpha\nbeta\ngamma";
    let index = LineIndex::build(doc);
    println!("line(1) = {:?}", index.line(doc, 1));
}

use std::cell::Cell;

struct HitCounter {
    count: Cell<u32>,
}

impl HitCounter {
    fn new() -> Self {
        HitCounter { count: Cell::new(0) }
    }

    // 接收 &self，却仍能修改内部计数
    fn hit(&self) -> u32 {
        let next = self.count.get() + 1;
        self.count.set(next);
        next
    }

    fn value(&self) -> u32 {
        self.count.get()
    }
}

