use std::borrow::Cow;

fn normalize(text: &str) -> Cow<'_, str> {
    if text.contains('\t') {
        // 需要修改：产生拥有型
        let replaced = text.replace('\t', "    ");
        Cow::Owned(replaced)
    } else {
        // 无需修改：零成本借用
        Cow::Borrowed(text)
    }
}

fn main() {
    let clean = "no tabs here";
    let dirty = "a\tb\tc";

    let n1 = normalize(clean);
    let n2 = normalize(dirty);
    println!("n1 = {:?} borrowed={}", n1, matches!(n1, Cow::Borrowed(_)));
    println!("n2 = {:?} owned={}", n2, matches!(n2, Cow::Owned(_)));
    println!("长度: {} vs {}", n1.len(), n2.len());
}

// 目标: 找到绝对值最大的元素并把它翻倍。
// 直接同时读写会冲突，这里分两阶段。

fn double_max_abs(values: &mut [i32]) -> Option<usize> {
    // 只读阶段: 只记录索引，不保留引用
    let target = values
        .iter()
        .enumerate()
        .max_by_key(|(_, v)| v.abs())
        .map(|(i, _)| i)?;

    // 可变阶段: 用索引修改，只读借用已结束
    values[target] *= 2;
    Some(target)
}

fn main() {
    let mut data = [-3, 7, -9, 2];
    let idx = double_max_abs(&mut data);
    println!("idx = {:?}, data = {:?}", idx, data);

    let empty: &mut [i32] = &mut [];
    println!("empty -> {:?}", double_max_abs(empty));
}

use std::borrow::Cow;
use std::collections::HashMap;

fn normalize(word: &str) -> Cow<'_, str> {
    if word.chars().any(|c| c.is_uppercase()) {
        Cow::Owned(word.to_lowercase())
    } else {
        Cow::Borrowed(word)
    }
}

fn top_words(text: &str, limit: usize) -> Vec<(String, usize)> {
    let mut counts: HashMap<Cow<'_, str>, usize> = HashMap::new();
    for raw in text.split_whitespace() {
        let word = normalize(raw.trim_matches(|c: char| !c.is_alphanumeric()));
        if word.is_empty() {
            continue;
        }
        *counts.entry(word).or_insert(0) += 1;
    }

    let mut pairs: Vec<(String, usize)> = counts
        .into_iter()
        .map(|(w, n)| (w.into_owned(), n))
        .collect();
    pairs.sort_by(|a, b| b.1.cmp(&a.1).then_with(|| a.0.cmp(&b.0)));
    pairs.truncate(limit);
    pairs
}

fn main() {
    let text = "Rust rust makes systems fast; fast safe code. Rust! safe systems";
    for (word, n) in top_words(text, 4) {
        println!("{}: {}", word, n);
    }
}

