#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum Door {
    Closed,
    Open,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum Event {
    Open,
    Close,
    Lock,
}

#[derive(Debug, PartialEq, Eq)]
enum TransitionError {
    AlreadyInState(Door),
    Locked,
}

fn transition(state: Door, event: Event) -> Result<Door, TransitionError> {
    match (state, event) {
        (Door::Closed, Event::Open) => Ok(Door::Open),
        (Door::Open, Event::Close) => Ok(Door::Closed),
        (Door::Closed, Event::Close) => Err(TransitionError::AlreadyInState(state)),
        (Door::Open, Event::Open) => Err(TransitionError::AlreadyInState(state)),
        (_, Event::Lock) => Err(TransitionError::Locked),
    }
}

fn main() {
    let mut state = Door::Closed;
    for event in [Event::Open, Event::Open, Event::Close, Event::Lock] {
        match transition(state, event) {
            Ok(next) => {
                println!("{:?} --{:?}--> {:?}", state, event, next);
                state = next;
            }
            Err(e) => println!("{:?} --{:?}--> 错误 {:?}", state, event, e),
        }
    }
    println!("最终状态 = {:?}", state);
}

