#[derive(Debug, PartialEq)]
enum ParseError {
    Empty,
    NotANumber(String),
    OutOfRange(i64),
}

fn parse_percent(text: &str) -> Result<u8, ParseError> {
    let trimmed = text.trim();
    if trimmed.is_empty() {
        return Err(ParseError::Empty);
    }
    let digits = trimmed.strip_suffix('%').unwrap_or(trimmed);
    let value: i64 = digits.parse().map_err(|_| ParseError::NotANumber(digits.to_string()))?;
    if !(0..=100).contains(&value) {
        return Err(ParseError::OutOfRange(value));
    }
    Ok(value as u8)
}

fn main() {
    for input in ["42%", " 100 ", "", "abc", "150%"] {
        match parse_percent(input) {
            Ok(v) => println!("{:?} -> {}", input, v),
            Err(e) => println!("{:?} -> 错误 {:?}", input, e),
        }
    }

    // 组合子: map_err 统一错误展示
    let msg = parse_percent("oops").map_err(|e| format!("{:?}", e));
    println!("combined = {:?}", msg);
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum Alignment {
    Left,
    Center,
    Right,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum Overflow {
    Wrap,
    Ellipsis,
}

// 按字符数（而非字节数）选取前 width 个字符，遇到多字节 UTF-8（如中文）不会 panic。
fn take_chars(text: &str, width: usize) -> String {
    text.chars().take(width).collect()
}

fn pad(text: &str, width: usize, align: Alignment) -> String {
    let len = text.chars().count();
    if len >= width {
        return text.to_string();
    }
    let total = width - len;
    match align {
        Alignment::Left => format!("{}{}", text, " ".repeat(total)),
        Alignment::Right => format!("{}{}", " ".repeat(total), text),
        Alignment::Center => {
            let left = total / 2;
            let right = total - left;
            format!("{}{}{}", " ".repeat(left), text, " ".repeat(right))
        }
    }
}

fn render(text: &str, width: usize, align: Alignment, overflow: Overflow) -> String {
    let shown = if text.chars().count() > width {
        match overflow {
            Overflow::Wrap => text.to_string(),
            Overflow::Ellipsis => {
                if width == 0 {
                    String::new()
                } else {
                    format!("{}…", take_chars(text, width - 1))
                }
            }
        }
    } else {
        text.to_string()
    };
    pad(&shown, width, align)
}

fn main() {
    println!("[{}]", render("hi", 6, Alignment::Left, Overflow::Wrap));
    println!("[{}]", render("hi", 6, Alignment::Right, Overflow::Wrap));
    println!("[{}]", render("hi", 6, Alignment::Center, Overflow::Wrap));
    println!("[{}]", render("toolong", 5, Alignment::Left, Overflow::Ellipsis));
    println!("[{}]", render("你好世界", 6, Alignment::Center, Overflow::Ellipsis));
    println!("[{}]", render("中文", 6, Alignment::Left, Overflow::Wrap));
}

#[derive(Debug, PartialEq)]
enum List {
    Cons(i32, Box<List>),
    Nil,
}

impl List {
    fn new() -> Self {
        List::Nil
    }

    fn push_front(self, value: i32) -> Self {
        List::Cons(value, Box::new(self))
    }

    fn len(&self) -> usize {
        match self {
            List::Cons(_, tail) => 1 + tail.len(),
            List::Nil => 0,
        }
    }

    fn sum(&self) -> i32 {
        match self {
            List::Cons(v, tail) => v + tail.sum(),
            List::Nil => 0,
        }
    }
}

fn main() {
    let list = List::new().push_front(3).push_front(2).push_front(1);
    println!("list = {:?}", list);
    println!("len = {}, sum = {}", list.len(), list.sum());
}

