    // 匹配 &Option<Config>，绑定默认是引用
    match config {
        Some(c) => format!("name={} retries={}", c.name, c.retries),
        None => String::from("<none>"),
    }
}

fn bump_retries(config: &mut Option<Config>) {
    match config {
        Some(c) => {
            // c 是 &mut Config
            c.retries += 1;
        }
        None => {}
    }
}

fn main() {
    let config = Some(Config { name: String::from("svc"), retries: 2 });
    println!("{}", describe(&config));
    println!("None -> {}", describe(&None));

    let mut mutable = config;
    bump_retries(&mut mutable);
    println!("after bump = {:?}", mutable);
}

#[derive(Debug, Clone, Copy, PartialEq)]
enum Event {
