use std::fmt::Display;

fn largest<T: PartialOrd + Copy>(items: &[T]) -> Option<T> {
    let mut best = *items.first()?;
    for &item in &items[1..] {
        if item > best {
            best = item;
        }
    }
    Some(best)
}

fn print_all<T: Display>(label: &str, items: &[T]) {
    print!("{}: ", label);
    for item in items {
        print!("{} ", item);
    }
    println!();
}

