    println!("largest chars = {:?}", largest(&['a', 'z', 'm']));
    println!("largest empty = {:?}", largest::<i32>(&[]));

    print_all("numbers", &[1, 2, 3]);
    print_all("words", &["alpha", "beta"]);
}

