struct Fibonacci {
    a: u64,
    b: u64,
    remaining: usize,
}

impl Fibonacci {
    fn new(count: usize) -> Self {
        Fibonacci { a: 0, b: 1, remaining: count }
    }
}

impl Iterator for Fibonacci {
    type Item = u64;

    fn next(&mut self) -> Option<u64> {
        if self.remaining == 0 {
            return None;
        }
        let current = self.a;
        let next = self.a + self.b;
        self.a = self.b;
        self.b = next;
        self.remaining -= 1;
        Some(current)
    }
}

fn main() {
    let fibs: Vec<u64> = Fibonacci::new(8).collect();
    println!("fibs={:?}", fibs);

    // 自定义迭代器直接接入标准适配器
    let even_fibs: Vec<u64> = Fibonacci::new(10).filter(|n| n % 2 == 0).collect();
    println!("even_fibs={:?}", even_fibs);

    let total: u64 = Fibonacci::new(10).sum();
    println!("total={}", total);
}

use std::cmp::Reverse;
use std::collections::{BinaryHeap, VecDeque};

fn window_sums(values: &[i32], k: usize) -> Vec<i32> {
    let mut window: VecDeque<i32> = VecDeque::new();
    let mut sums = Vec::new();
    for &v in values {
        window.push_back(v);
        if window.len() > k {
            window.pop_front();
        }
        if window.len() == k {
            sums.push(window.iter().sum());
        }
    }
    sums
}

fn main() {
    println!("windows={:?}", window_sums(&[1, 2, 3, 4, 5], 3));

    let mut max_heap = BinaryHeap::new();
    for v in [5, 1, 9, 3, 7] {
        max_heap.push(v);
    }
    println!("max={:?}", max_heap.pop());

    // 最小堆：用 Reverse 反转比较顺序
    let mut min_heap: BinaryHeap<Reverse<i32>> = BinaryHeap::new();
    for v in [5, 1, 9, 3, 7] {
        min_heap.push(Reverse(v));
    }
    let two_smallest: Vec<i32> = (0..2)
        .filter_map(|_| min_heap.pop().map(|Reverse(v)| v))
        .collect();
    println!("two_smallest={:?}", two_smallest);
}

