use std::collections::HashMap;

fn aggregate(logs: &[&str]) -> (HashMap<String, u32>, HashMap<String, u32>) {
    let mut by_level: HashMap<String, u32> = HashMap::new();
    let mut by_source: HashMap<String, u32> = HashMap::new();
    for line in logs {
        let mut parts = line.split_whitespace();
        let level = parts.next().unwrap_or("UNKNOWN");
        let source = parts.next().unwrap_or("unknown");
        *by_level.entry(level.to_string()).or_insert(0) += 1;
        *by_source.entry(source.to_string()).or_insert(0) += 1;
    }
    (by_level, by_source)
}

fn top_k(counts: &HashMap<String, u32>, k: usize) -> Vec<(String, u32)> {
    let mut entries: Vec<(String, u32)> = counts
        .iter()
        .map(|(name, &count)| (name.clone(), count))
        .collect();
    // 次数降序，次数相同按名称升序，保证确定输出
    entries.sort_by(|a, b| b.1.cmp(&a.1).then_with(|| a.0.cmp(&b.0)));
    entries.truncate(k);
    entries
}

fn main() {
    let logs = [
        "INFO api started",
        "WARN db slow",
        "INFO worker ready",
        "ERROR api timeout",
        "INFO api handled",
        "ERROR db deadlock",
    ];
    let (by_level, by_source) = aggregate(&logs);

    let mut levels: Vec<(&String, &u32)> = by_level.iter().collect();
    levels.sort();
    for (level, count) in levels {
        println!("level {}={}", level, count);
    }

    println!("top_sources={:?}", top_k(&by_source, 2));
}

