use std::num::ParseIntError;

fn parse_pair(text: &str) -> Result<(i32, i32), ParseIntError> {
    let (left, right) = text.split_once(',').unwrap_or((text, "0"));
    let a = left.trim().parse::<i32>()?;
    let b = right.trim().parse::<i32>()?;
    Ok((a, b))
}

fn sum_pairs(texts: &[&str]) -> Result<i32, ParseIntError> {
    let mut total = 0;
    for text in texts {
        let (a, b) = parse_pair(text)?;
        total += a + b;
    }
    Ok(total)
}

fn main() {
    println!("pair={:?}", parse_pair("3, 4"));
    println!("pair={:?}", parse_pair("3"));
    println!("total={:?}", sum_pairs(&["1,2", "10,20"]));
    println!("total_err={}", sum_pairs(&["1,2", "x,3"]).is_err());
}

use std::error::Error;
use std::fmt;
use std::num::ParseIntError;

#[derive(Debug)]
enum ConfigError {
    MissingField(String),
    InvalidNumber { field: String, source: ParseIntError },
}

impl fmt::Display for ConfigError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            ConfigError::MissingField(name) => write!(f, "missing field: {name}"),
            ConfigError::InvalidNumber { field, .. } => {
                write!(f, "invalid number for field: {field}")
            }
        }
    }
}

impl Error for ConfigError {
    fn source(&self) -> Option<&(dyn Error + 'static)> {
        match self {
            ConfigError::InvalidNumber { source, .. } => Some(source),
            ConfigError::MissingField(_) => None,
        }
    }
}

fn parse_field(config: &[(String, String)], key: &str) -> Result<i32, ConfigError> {
    let value = config
        .iter()
        .find(|(k, _)| k == key)
        .map(|(_, v)| v.as_str())
        .ok_or_else(|| ConfigError::MissingField(key.to_string()))?;
    value.parse::<i32>().map_err(|source| ConfigError::InvalidNumber {
        field: key.to_string(),
        source,
    })
}

fn main() {
    let config = vec![("port".to_string(), "8080".to_string())];
    println!("port={:?}", parse_field(&config, "port"));

    let bad = vec![("port".to_string(), "abc".to_string())];
    match parse_field(&bad, "port") {
        Ok(v) => println!("ok={v}"),
        Err(e) => {
            println!("top={e}");
            if let Some(src) = e.source() {
                println!("source={src}");
            }
        }
    }
    match parse_field(&config, "host") {
        Ok(v) => println!("ok={v}"),
        Err(e) => println!("top={e}"),
    }
}

