}

impl fmt::Display for AppError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            AppError::Number(e) => write!(f, "number error: {e}"),
            AppError::Empty => write!(f, "input was empty"),
        }
    }
}

impl Error for AppError {
    fn source(&self) -> Option<&(dyn Error + 'static)> {
        match self {
            AppError::Number(e) => Some(e),
            AppError::Empty => None,
        }
    }
}

// ? 会自动调用这个 From
impl From<ParseIntError> for AppError {
    fn from(e: ParseIntError) -> Self {
        AppError::Number(e)
    }
}

fn first_number(items: &[&str]) -> Result<i32, AppError> {
    let text = items.iter().find(|s| !s.is_empty()).ok_or(AppError::Empty)?;
    Ok(text.parse::<i32>()?)
}

fn main() {
    println!("ok={:?}", first_number(&["", "42"]));
    println!("empty={:?}", first_number(&["", ""]));
    match first_number(&["x"]) {
        Ok(v) => println!("ok={v}"),
        Err(AppError::Number(e)) => println!("number err: {e}"),
        Err(AppError::Empty) => println!("empty err"),
    }
}

use std::error::Error;
use std::fmt;

#[derive(Debug)]
struct NotFound(String);

impl fmt::Display for NotFound {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "not found: {}", self.0)
    }
}

impl Error for NotFound {}

// 返回 Box<dyn Error>：函数可以传播任意错误类型
fn run(input: &str) -> Result<i32, Box<dyn Error>> {
    if input.is_empty() {
        return Err(NotFound("empty input".to_string()).into());
    }
    let value = input.parse::<i32>()?; // ParseIntError 自动装箱
    Ok(value * 2)
}

fn main() {
    println!("ok={:?}", run("21"));

    match run("") {
        Ok(v) => println!("ok={v}"),
        Err(e) => {
            println!("display={e}");
            // 尝试还原成具体类型
            if let Some(nf) = e.downcast_ref::<NotFound>() {
                println!("downcast=not-found {}", nf.0);
            }
        }
    }
    println!("parse_display={}", run("x").unwrap_err());
}

