mod lib_logic {
    pub fn is_prime(n: u64) -> bool {
        if n < 2 {
            return false;
        }
        let mut i = 2;
        while i * i <= n {
            if n % i == 0 {
                return false;
            }
            i += 1;
        }
        true
    }

    pub fn primes_up_to(limit: u64) -> Vec<u64> {
        (2..=limit).filter(|&n| is_prime(n)).collect()
    }
}

fn main() {
    println!("primes={:?}", lib_logic::primes_up_to(20));
    println!("count={}", lib_logic::primes_up_to(50).len());
}

