use std::panic;

#[derive(Debug, PartialEq)]
struct Stack {
    items: Vec<i32>,
}

impl Stack {
    fn new() -> Self {
        Stack { items: Vec::new() }
    }
    fn push(&mut self, value: i32) {
        self.items.push(value);
    }
    fn pop(&mut self) -> i32 {
        self.items.pop().expect("pop on empty stack")
    }
    fn len(&self) -> usize {
        self.items.len()
    }
}

fn sample_stack() -> Stack {
    let mut s = Stack::new();
    s.push(1);
    s.push(2);
    s
}

fn main() {
    // 夹具驱动的断言
    let mut s = sample_stack();
    assert_eq!(s.len(), 2);
    assert_eq!(s.pop(), 2);
    assert_eq!(s.pop(), 1);
    println!("fixture_ok={}", s.len());

    // 用 catch_unwind 观察‘应当 panic’的行为
    let result = panic::catch_unwind(|| {
        let mut empty = Stack::new();
        empty.pop()
    });
    println!("panicked={}", result.is_err());
}

fn render_report(items: &[(&str, i32)]) -> Vec<String> {
    let mut lines = Vec::new();
    let total: i32 = items.iter().map(|(_, v)| *v).sum();
    lines.push(format!("total={total}"));
    for (name, value) in items {
        lines.push(format!("{name}: {value}"));
    }
    lines
}

fn main() {
    let report = render_report(&[("apples", 3), ("pears", 5)]);
    let expected = vec!["total=8", "apples: 3", "pears: 5"];
    assert_eq!(report, expected);
