fn parse_line(line: &str) -> Result<Vec<String>, String> {
    let mut fields = Vec::new();
    let mut current = String::new();
    let mut in_quotes = false;
    let mut chars = line.chars().peekable();
    while let Some(c) = chars.next() {
        match c {
            '"' => {
                if in_quotes && chars.peek() == Some(&'"') {
                    current.push('"');
                    chars.next();
                } else {
                    in_quotes = !in_quotes;
                }
            }
            ',' if !in_quotes => {
                fields.push(std::mem::take(&mut current));
            }
            _ => current.push(c),
        }
    }
    if in_quotes {
        return Err(String::from("unterminated quoted field"));
    }
    fields.push(current);
    Ok(fields)
}

fn main() {
    assert_eq!(parse_line("a,b,c").unwrap(), vec!["a", "b", "c"]);
    assert_eq!(
        parse_line("\"hello, world\",42").unwrap(),
        vec!["hello, world", "42"]
    );
    assert_eq!(
        parse_line("\"a\"\"b\",c").unwrap(),
        vec!["a\"b", "c"]
    );
    println!("simple={:?}", parse_line("a,b,c").unwrap());
    println!("quoted={:?}", parse_line("\"x,y\",z").unwrap());
    println!("escaped={:?}", parse_line("\"p\"\"q\"").unwrap());
    println!("error={:?}", parse_line("\"open").unwrap_err());
}

