use std::cell::Cell;

struct Metrics {
    hits: Cell<u32>,
    enabled: Cell<bool>,
}

impl Metrics {
    fn new() -> Self {
        Metrics { hits: Cell::new(0), enabled: Cell::new(true) }
    }

    fn record(&self) {
        if self.enabled.get() {
            self.hits.set(self.hits.get() + 1);
        }
    }

    fn disable(&self) {
        self.enabled.set(false);
    }

    fn hits(&self) -> u32 {
        self.hits.get()
    }
}

fn main() {
    let m = Metrics::new();
    m.record();
    m.record();
