use std::cell::RefCell;
use std::sync::atomic::{AtomicI32, Ordering};
use std::sync::Mutex;

// 1) 不可变重建：最易推理
fn rebuilt_add(values: &[i32], delta: i32) -> Vec<i32> {
    values.iter().map(|v| v + delta).collect()
}

// 2) 单线程内部可变：RefCell
fn refcell_add(cell: &RefCell<i32>, delta: i32) {
    *cell.borrow_mut() += delta;
}

// 3) 跨线程：原子
fn atomic_add(counter: &AtomicI32, delta: i32) {
    counter.fetch_add(delta, Ordering::SeqCst);
}

// 4) 跨线程可变结构：Mutex
fn mutex_add(lock: &Mutex<Vec<i32>>, value: i32) {
    lock.lock().unwrap().push(value);
}

fn main() {
    println!("rebuilt={:?}", rebuilt_add(&[1, 2, 3], 10));

    let cell = RefCell::new(0);
    refcell_add(&cell, 5);
    refcell_add(&cell, 7);
    println!("refcell={}", *cell.borrow());

    let atomic = AtomicI32::new(0);
    atomic_add(&atomic, 3);
    atomic_add(&atomic, 4);
    println!("atomic={}", atomic.load(Ordering::SeqCst));

    let lock = Mutex::new(Vec::new());
    mutex_add(&lock, 9);
    println!("mutex={:?}", *lock.lock().unwrap());
}

use std::cell::RefCell;
use std::rc::Rc;

type Observer = Box<dyn FnMut(i32)>;

struct Subject {
    value: i32,
    observers: RefCell<Vec<Observer>>,
    log: Rc<RefCell<Vec<String>>>,
}

impl Subject {
    fn new(log: Rc<RefCell<Vec<String>>>) -> Self {
        Subject { value: 0, observers: RefCell::new(Vec::new()), log }
    }

    fn subscribe(&self, observer: Observer) {
        self.observers.borrow_mut().push(observer);
    }

    fn set(&mut self, value: i32) {
        self.value = value;
        // 先把回调临时取出，避免通知期间重复借用 observers
        let mut observers = self.observers.replace(Vec::new());
        for observer in observers.iter_mut() {
            observer(value);
        }
        self.observers.replace(observers);
    }
}

fn main() {
    let log = Rc::new(RefCell::new(Vec::new()));
    let log_a = Rc::clone(&log);
    let log_b = Rc::clone(&log);

    let mut subject = Subject::new(Rc::clone(&log));
    subject.subscribe(Box::new(move |v| log_a.borrow_mut().push(format!("a:{v}"))));
    subject.subscribe(Box::new(move |v| log_b.borrow_mut().push(format!("b:{v}"))));

    subject.set(1);
    subject.set(2);

    for entry in log.borrow().iter() {
        println!("{entry}");
    }
    println!("observer_count={}", subject.observers.borrow().len());
}

