    let account_b = Arc::new(Mutex::new(50i32));

    // 统一锁顺序：总是先 a 后 b，避免交叉死锁
    let (a1, b1) = (Arc::clone(&account_a), Arc::clone(&account_b));
    let t1 = thread::spawn(move || {
