use std::sync::atomic::{AtomicBool, AtomicUsize, Ordering};
use std::sync::Arc;
use std::thread;

fn main() {
    let data = Arc::new(AtomicUsize::new(0));
    let ready = Arc::new(AtomicBool::new(false));

    let producer_data = Arc::clone(&data);
    let producer_ready = Arc::clone(&ready);
    let producer = thread::spawn(move || {
        // 先写数据，再用 Release 发布
        producer_data.store(42, Ordering::Relaxed);
        producer_ready.store(true, Ordering::Release);
    });

    let consumer_data = Arc::clone(&data);
    let consumer_ready = Arc::clone(&ready);
    let consumer = thread::spawn(move || {
        // Acquire 读取标志，保证能看到 Release 之前的所有写
        while !consumer_ready.load(Ordering::Acquire) {
            std::hint::spin_loop();
        }
        consumer_data.load(Ordering::Relaxed)
    });

    producer.join().unwrap();
    let seen = consumer.join().unwrap();
    println!("seen={}", seen);

    // 展示 Relaxed 独立自增仍然原子
    let counter = AtomicUsize::new(0);
    for _ in 0..3 {
        counter.fetch_add(1, Ordering::Relaxed);
    }
    println!("relaxed_count={}", counter.load(Ordering::Relaxed));
}

use std::sync::atomic::{AtomicUsize, Ordering};
use std::sync::Arc;
use std::thread;

fn lock_free_add(counter: &AtomicUsize, delta: usize) {
    let mut current = counter.load(Ordering::SeqCst);
    loop {
        let next = current + delta;
        match counter.compare_exchange(current, next, Ordering::SeqCst, Ordering::SeqCst) {
            Ok(_) => return,
            Err(actual) => current = actual,
        }
    }
}

fn main() {
    let counter = Arc::new(AtomicUsize::new(0));
    let mut handles = Vec::new();
    for _ in 0..4 {
        let shared = Arc::clone(&counter);
        handles.push(thread::spawn(move || {
            for _ in 0..250 {
                lock_free_add(&shared, 1);
            }
        }));
    }
    for handle in handles {
        handle.join().unwrap();
    }
    println!("counter={}", counter.load(Ordering::SeqCst));

    // 带版本号的 CAS：高 32 位存版本、低 32 位存值
    let packed = AtomicUsize::new((0usize << 32) | 0);
    let current = packed.load(Ordering::SeqCst);
    let version = current >> 32;
    let value = current & 0xffff_ffff;
    let next = ((version + 1) << 32) | (value + 10);
    packed.compare_exchange(current, next, Ordering::SeqCst, Ordering::SeqCst).unwrap();
    let after = packed.load(Ordering::SeqCst);
    println!("value={} version={}", after & 0xffff_ffff, after >> 32);
}

use std::sync::mpsc::{self, Sender};
use std::sync::{Arc, Mutex};
use std::thread;

type Job = Box<dyn FnOnce() + Send + 'static>;

struct Pool {
    sender: Option<Sender<Job>>,
    workers: Vec<thread::JoinHandle<()>>,
}

impl Pool {
    fn new(size: usize) -> Pool {
        let (job_tx, job_rx) = mpsc::channel::<Job>();
        let job_rx = Arc::new(Mutex::new(job_rx));

        let mut workers = Vec::new();
        for _ in 0..size {
            let rx = Arc::clone(&job_rx);
            workers.push(thread::spawn(move || loop {
                // 只在取任务时短时间持锁，执行任务在锁外
                let job = {
                    let guard = rx.lock().unwrap();
                    guard.recv()
                };
                match job {
                    Ok(job) => job(),
                    Err(_) => break,
                }
            }));
        }
        Pool { sender: Some(job_tx), workers }
    }

    fn submit<F: FnOnce() + Send + 'static>(&self, task: F) {
        self.sender.as_ref().unwrap().send(Box::new(task)).unwrap();
    }

    fn shutdown(mut self) {
        drop(self.sender.take());
        for worker in self.workers.drain(..) {
            worker.join().unwrap();
        }
    }
}

fn main() {
    let (result_tx, result_rx) = mpsc::channel::<usize>();
    let pool = Pool::new(3);

    for id in 1..=5usize {
        let tx = result_tx.clone();
        pool.submit(move || {
            let sum: usize = (1..=id * 10).map(|x| x * x).sum();
            tx.send(sum).unwrap();
        });
    }
    drop(result_tx); // 丢弃唯一剩余发送端，结果循环才能结束
    pool.shutdown();

    let mut results: Vec<usize> = result_rx.iter().collect();
    results.sort();
    println!("results={:?}", results);
}

