// 最简单的宏：打印一个带标签的值
macro_rules! show {
    ($label:expr, $value:expr) => {
        println!("{}={}", $label, $value);
    };
}

// 多模式：计算平方
macro_rules! square {
    ($x:expr) => {
        ($x) * ($x)
    };
}

// 用分号分隔的可变参数
macro_rules! sum_all {
    ($($value:expr),* $(,)?) => {{
        let mut total = 0;
        $( total += $value; )*
        total
    }};
}

fn main() {
    show!("answer", 42);
    println!("square(5)={}", square!(5));
    println!("sum={}", sum_all!(1, 2, 3, 4));
    println!("sum_empty={}", sum_all!());
}

// 生成多个名字为 name_0、name_1… 的变量需要 concat_idents 类能力，
// 标准 macro_rules! 不直接支持；这里演示合法的重复与卫生性。

macro_rules! sum_and_print {
    ($($value:expr),* $(,)?) => {{
        let mut tmp = 0; // 卫生：不会与调用者的 tmp 冲突
        // 每个表达式只求值一次，存进 v
        $( let v = $value; tmp += v; )*
        println!("sum={}", tmp);
    }};
}

// 用 tt 片段逐字接收
macro_rules! apply_to {
    ($func:ident, $($arg:expr),*) => {
        $func($($arg),*)
    };
}

fn double(x: i32) -> i32 {
    x * 2
}

fn main() {
    let tmp = 999; // 与宏内的 tmp 不冲突
    sum_and_print!(1, 2, 3);
    println!("outer_tmp={}", tmp);

    println!("applied={}", apply_to!(double, 21));
}

macro_rules! my_vec {
    () => { Vec::new() };
    ($($value:expr),+ $(,)?) => {{
        let mut v = Vec::new();
        $( v.push($value); )+
        v
    }};
    ($value:expr; $count:expr) => {{
        let mut v = Vec::new();
        // 先把表达式求值一次，后续只 clone，不重复求值
        let value = $value;
        for _ in 0..$count {
            v.push(value.clone());
        }
        v
    }};
}

fn main() {
    let empty: Vec<i32> = my_vec![];
    println!("empty={:?}", empty);

    let listed = my_vec![1, 2, 3];
    println!("listed={:?}", listed);

    let repeated = my_vec!["x"; 3];
    println!("repeated={:?}", repeated);
}

// 手写出‘派生宏会生成的代码’，理解产物形态（真实派生宏由 proc-macro 根据输入生成）。
use std::fmt;

trait Describe {
    fn describe(&self) -> String;
}

struct Point {
    x: i32,
    y: i32,
}

// 等价于 `#[derive(Describe)]` 展开出来的代码
impl Describe for Point {
    fn describe(&self) -> String {
        format!("Point has 2 fields")
    }
}

impl fmt::Display for Point {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{}", self.describe())
    }
}

fn main() {
    let p = Point { x: 3, y: 4 };
    println!("describe={}", p.describe());
    println!("display={}", p);
    let _ = (p.x, p.y);
}

