// 例 1：把 slice 分成前后两半 —— 标准库已有安全 API，无需 unsafe
fn split_half(values: &[i32]) -> (&[i32], &[i32]) {
    values.split_at(values.len() / 2)
}

// 例 2：读取一个来自裸指针的值 —— 需要 unsafe，并写明不变式
/// # Safety
/// `ptr` 必须指向一个已初始化、对齐且在本调用期间存活的 i32。
unsafe fn read_i32(ptr: *const i32) -> i32 {
    // 调用者已保证 ptr 有效，故这次解引用是安全的
    *ptr
}

fn main() {
    let (a, b) = split_half(&[1, 2, 3, 4]);
    println!("left={:?} right={:?}", a, b);

    let value = 7;
    let ptr: *const i32 = &value;
    // 安全前提：ptr 仍指向存活的局部 value
    let read = unsafe { read_i32(ptr) };
    println!("read={}", read);
}

fn main() {
    let data: Vec<i32> = vec![10, 20, 30, 40];
    let ptr = data.as_ptr();
    let len = data.len();

    // 前提：data 存活、ptr 对齐、len 正确 -> 构造安全
    let slice: &[i32] = unsafe { std::slice::from_raw_parts(ptr, len) };
    println!("slice={:?}", slice);
    println!("sum={}", slice.iter().sum::<i32>());

    // 只取前两个元素（len 更小是允许的，只要不超过原长度）
    let head: &[i32] = unsafe { std::slice::from_raw_parts(ptr, 2) };
    println!("head={:?}", head);

    // 空切片：非空指针 + 长度 0 或对齐的悬垂指针均可
    let empty: &[i32] = unsafe { std::slice::from_raw_parts(data.as_ptr(), 0) };
    println!("empty_len={}", empty.len());
}

/// 从裸指针指向的连续 i32 数组中读取下标 `index` 处的元素。
///
/// # Safety
/// - `ptr` 必须指向至少 `len` 个已初始化、对齐的 i32。
/// - `index` 必须小于 `len`。
/// - 所指内存在本次调用期间必须保持有效且不被可变借用别名。
unsafe fn read_at(ptr: *const i32, len: usize, index: usize) -> i32 {
    debug_assert!(index < len);
    // SAFETY: 调用者保证 index < len 且 ptr 覆盖 len 个有效元素
    *ptr.add(index)
}

fn safe_read(values: &[i32], index: usize) -> Option<i32> {
    if index >= values.len() {
        return None;
    }
    // SAFETY: 已检查 index < values.len()，且 values 在整个调用期间存活
    Some(unsafe { read_at(values.as_ptr(), values.len(), index) })
}

fn main() {
    let values = [5, 6, 7, 8];
    println!("at0={:?}", safe_read(&values, 0));
    println!("at3={:?}", safe_read(&values, 3));
    println!("at9={:?}", safe_read(&values, 9));
}

/// 把可变切片在 `mid` 处拆成两个不相交的可变切片。
/// 对外签名完全安全：越界时 panic，不会 UB。
fn split_at_mut(mut values: &mut [i32], mid: usize) -> (&mut [i32], &mut [i32]) {
    let len = values.len();
    assert!(mid <= len, "mid {mid} out of range {len}");
    let ptr = values.as_mut_ptr();
    // SAFETY:
    // - mid <= len 已断言；
    // - 两个切片区间 [0,mid) 与 [mid,len) 不相交；
    // - 原 values 的独占借用被消费，拆分后仍不重叠。
    unsafe {
        let left = std::slice::from_raw_parts_mut(ptr, mid);
        let right = std::slice::from_raw_parts_mut(ptr.add(mid), len - mid);
        (left, right)
    }
}

fn main() {
    let mut data = vec![1, 2, 3, 4, 5];
    {
        let (left, right) = split_at_mut(&mut data, 2);
        left[0] = 100;
        right[0] = 300;
    }
    println!("data={:?}", data);

    let mut small = [9];
    let (a, b) = split_at_mut(&mut small, 1);
    println!("a={:?} b={:?}", a, b);
}

// 导出一个 C ABI 函数：可在纯 Rust 内自调用（无需链接外部库）
#[unsafe(no_mangle)]
pub extern "C" fn rust_add(a: i32, b: i32) -> i32 {
    a + b
}

#[unsafe(no_mangle)]
pub extern "C" fn rust_dot(x1: f64, y1: f64, x2: f64, y2: f64) -> f64 {
    x1 * x2 + y1 * y2
}

// 用 extern block 声明（假装来自 C 库）；这里指向本文件的导出函数。
// 声明要与定义分开放进子模块，避免同名重定义。
mod ffi {
    unsafe extern "C" {
        pub fn rust_add(a: i32, b: i32) -> i32;
    }
}

fn main() {
    println!("direct={}", rust_add(2, 3));
    println!("dot={}", rust_dot(1.0, 2.0, 3.0, 4.0));
    // 通过 extern 声明调用（ABI 相同）
    let via_ffi = unsafe { ffi::rust_add(10, 20) };
    println!("via_ffi={}", via_ffi);
}

