use std::os::raw::c_char;

/// 一个 C ABI 函数：统计 NUL 结尾的 C 字符串字节长度（不含结尾 0）。
/// 不依赖 libc；c_char 来自 std::os::raw。
#[unsafe(no_mangle)]
pub unsafe extern "C" fn rust_strlen(s: *const c_char) -> usize {
    if s.is_null() {
        return 0;
    }
    let mut len = 0usize;
    // SAFETY: 调用者保证 s 指向一个 NUL 结尾的有效 C 字符串。
    while *s.add(len) != 0 {
        len += 1;
    }
    len
}

mod ffi {
    use std::os::raw::c_char;
    unsafe extern "C" {
        pub fn rust_strlen(s: *const c_char) -> usize;
    }
}

fn main() {
    // C 风格字符串以 0 字节结尾
    let buffer = b"hello\0";
    let ptr = buffer.as_ptr() as *const c_char;
    // SAFETY: buffer 以 0 结尾且在本调用期间存活
    let length = unsafe { ffi::rust_strlen(ptr) };
    println!("len={}", length);
    println!("null_len={}", unsafe { ffi::rust_strlen(std::ptr::null()) });
    println!("note=c_char comes from std::os::raw, no libc crate needed");
}

