    flag: u8,
    value: u32,
}

fn main() {
    println!("c_size={}", std::mem::size_of::<CPair>());
    println!("c_align={}", std::mem::align_of::<CPair>());
    println!("rust_size={}", std::mem::size_of::<RustPair>());

    // repr(C) 字段偏移可预测：u16(2) + u8(1) + 填充(1) + u32(4) = 8
    let value = CPair { id: 1, flag: 2, value: 3 };
    let base = &value as *const CPair as usize;
    let id_offset = &value.id as *const u16 as usize - base;
    let flag_offset = &value.flag as *const u8 as usize - base;
    let value_offset = &value.value as *const u32 as usize - base;
    println!("offsets={} {} {}", id_offset, flag_offset, value_offset);
}

use std::collections::HashSet;
use std::time::Instant;

fn dedup_quadratic(values: &[u32]) -> Vec<u32> {
    let mut out: Vec<u32> = Vec::new();
    for &v in values {
        if !out.contains(&v) {
            out.push(v);
        }
    }
    out
}

fn dedup_hash(values: &[u32]) -> Vec<u32> {
    let mut seen: HashSet<u32> = HashSet::new();
    let mut out: Vec<u32> = Vec::new();
    for &v in values {
        if seen.insert(v) {
            out.push(v);
        }
    }
    out
}

fn main() {
    // 构造含大量重复的输入
    let input: Vec<u32> = (0..200).map(|i| i % 20).collect();

    let start = Instant::now();
    let a = dedup_quadratic(&input);
    let quad = start.elapsed();

    let start = Instant::now();
    let b = dedup_hash(&input);
    let hash = start.elapsed();

    // 确定性断言：两种实现必须得出相同结果与正确长度
    assert_eq!(a, b);
    assert_eq!(a.len(), 20);
    assert_eq!(b.len(), 20);

    // 耗时只作参考（不参与断言，也不打印，因噪声大且依赖机器）
    std::hint::black_box(quad);
    std::hint::black_box(hash);
    println!("equal={}", a == b);
    println!("count={}", a.len());
}

