    #[test]
    fn escapes_round_trip_and_rejects_truncation() {
        let title = "tab\tline\nback\\slash";
        assert_eq!(unescape(&escape(title)).unwrap(), title);
        assert!(unescape("trailing\\").is_err());
    }
    #[test]
    fn persistence_keeps_ids_and_errors_do_not_erase_data() {
