use std::collections::BTreeMap;
use std::fs;
use std::path::{Path, PathBuf};
use std::sync::{mpsc, Arc, Mutex};
use std::thread;
use std::time::{SystemTime, UNIX_EPOCH};

type Counts = BTreeMap<String, u64>;
struct Job { index: usize, path: PathBuf }
struct Event { index: usize, name: String, result: Result<Counts, String> }
struct Report { counts: Counts, errors: Vec<(String, String)>, processed: usize }

fn count_words(text: &str) -> Counts {
    let mut counts = BTreeMap::new();
    for word in text.split(|c: char| !c.is_alphanumeric()).filter(|word| !word.is_empty()) {
        let normalized: String = word.chars().flat_map(char::to_lowercase).collect();
        *counts.entry(normalized).or_insert(0) += 1;
    }
    counts
}

fn count_file(path: &Path) -> Result<Counts, String> {
    fs::read_to_string(path).map(|text| count_words(&text)).map_err(|error| {
        match error.kind() {
            std::io::ErrorKind::NotFound => "not-found",
            std::io::ErrorKind::InvalidData => "invalid-utf8",
            _ => "io-error",
        }.to_string()
    })
}

fn worker(receiver: Arc<Mutex<mpsc::Receiver<Job>>>, sender: mpsc::Sender<Event>) -> Result<(), String> {
    loop {
        // Only receive is serialized. File I/O and counting happen after the
        // guard is dropped, allowing all workers to process different files.
        let job = {
            let receiver = receiver.lock().map_err(|_| "job queue poisoned")?;
            receiver.recv()
        };
        let job = match job { Ok(job) => job, Err(_) => break };
        // Invalid input is a result for this job, never a worker shutdown.
        // In particular, roots have no file_name and must not strand a sender.
        let (name, result) = match job.path.file_name() {
            Some(name) => (name.to_string_lossy().into_owned(), count_file(&job.path)),
            None => (job.path.display().to_string(), Err("missing-filename".into())),
        };
        let event = Event { index: job.index, name, result };
        if sender.send(event).is_err() { break; }
    }
    Ok(())
}

fn pipeline(paths: Vec<PathBuf>, workers: usize, capacity: usize) -> Result<Report, String> {
    if workers == 0 || capacity == 0 { return Err("workers and capacity must be positive".into()); }
    let submitted = paths.len();
    let (job_tx, job_rx) = mpsc::sync_channel(capacity);
    let queue = Arc::new(Mutex::new(job_rx));
    let (result_tx, result_rx) = mpsc::channel();
    let mut events = thread::scope(|scope| -> Result<Vec<Event>, String> {
        // A separate producer provides backpressure without blocking result
        // collection when the bounded job queue fills.
