use std::collections::BTreeMap;
use std::future::Future;
use std::pin::Pin;
use std::sync::atomic::{AtomicBool, AtomicUsize, Ordering};
use std::sync::{mpsc, Arc, Mutex};
use std::task::{Context, Poll, Wake, Waker};
use std::thread;

#[derive(Debug, Clone, PartialEq, Eq)]
enum TaskError { Cancelled, Ffi(i32) }
type Outcome = Result<i32, TaskError>;

/// C callers may pass null to receive -1. Any other pointer must identify one
/// live, aligned, exclusively writable i32. No Rust panic crosses the ABI.
/// # Safety
/// A non-null `output` must satisfy the writable-pointer contract above.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn qfli_capstone166_double(value: i32, output: *mut i32) -> i32 {
    if output.is_null() { return -1; }
    match value.checked_mul(2) {
        Some(result) => {
            // SAFETY: the external caller owns the writable output slot.
            unsafe { output.write(result); }
            0
        }
        None => -2,
    }
}

unsafe extern "C" {
    // This portable example reimports its own exported symbol through the C
    // ABI. A separately built C library can implement the same signature.
    #[link_name = "qfli_capstone166_double"]
    fn c_double(value: i32, output: *mut i32) -> i32;
}

fn checked_double(value: i32) -> Outcome {
    let mut output = 0;
    // SAFETY: this stack slot remains aligned, writable, and live for the call.
    let status = unsafe { c_double(value, &mut output) };
    if status == 0 { Ok(output) } else { Err(TaskError::Ffi(status)) }
}

struct EventState { result: Option<Outcome>, waker: Option<Waker> }
struct Event { state: Mutex<EventState> }
impl Event {
    fn new() -> Self { Self { state: Mutex::new(EventState { result: None, waker: None }) } }
    fn complete(&self, result: Outcome) -> bool {
        let waker = {
            let mut state = self.state.lock().expect("event lock");
            if state.result.is_some() { return false; }
            state.result = Some(result);
            state.waker.take()
        };
        // Never invoke user scheduling logic while holding the event mutex.
        if let Some(waker) = waker { waker.wake(); }
        true
    }
    fn cancel(&self) -> bool { self.complete(Err(TaskError::Cancelled)) }
}

struct WaitEvent {
    event: Arc<Event>,
    first_pending: Option<mpsc::SyncSender<()>>,
    pending_count: Arc<AtomicUsize>,
}
impl Future for WaitEvent {
    type Output = Outcome;
    fn poll(mut self: Pin<&mut Self>, context: &mut Context<'_>) -> Poll<Outcome> {
        let event = Arc::clone(&self.event);
        let mut state = event.state.lock().expect("event lock");
        if let Some(result) = &state.result { return Poll::Ready(result.clone()); }
        // Checking readiness and registering the waker under the same lock
        // prevents an event being delivered between those two operations.
        state.waker = Some(context.waker().clone());
        if let Some(started) = self.first_pending.take() {
            self.pending_count.fetch_add(1, Ordering::Relaxed);
            let _ = started.send(());
        }
        Poll::Pending
    }
}

struct TaskWake { id: usize, ready: mpsc::Sender<usize>, queued: AtomicBool }
impl TaskWake {
    fn schedule(&self) {
        if !self.queued.swap(true, Ordering::AcqRel) {
            let _ = self.ready.send(self.id);
        }
    }
}
impl Wake for TaskWake {
    fn wake(self: Arc<Self>) { self.schedule(); }
    fn wake_by_ref(self: &Arc<Self>) { self.schedule(); }
}

struct Task { future: Pin<Box<dyn Future<Output = Outcome>>>, wake: Arc<TaskWake> }
struct Executor {
    tasks: BTreeMap<usize, Task>,
    ready_tx: mpsc::Sender<usize>,
    ready_rx: mpsc::Receiver<usize>,
}
impl Executor {
    fn new() -> Self {
        let (ready_tx, ready_rx) = mpsc::channel();
        Self { tasks: BTreeMap::new(), ready_tx, ready_rx }
    }
    fn spawn(&mut self, id: usize, future: impl Future<Output = Outcome> + 'static) -> Result<(), String> {
        if self.tasks.contains_key(&id) { return Err("duplicate task id".into()); }
        let wake = Arc::new(TaskWake { id, ready: self.ready_tx.clone(), queued: AtomicBool::new(false) });
        self.tasks.insert(id, Task { future: Box::pin(future), wake: Arc::clone(&wake) });
        wake.schedule();
        Ok(())
    }
    fn run(&mut self) -> Result<BTreeMap<usize, Outcome>, String> {
        let mut results = BTreeMap::new();
        while !self.tasks.is_empty() {
            // Block for an actual initial-ready/wake event. Pending futures are
            // not repeatedly polled, and no sleep/busy-wait loop is involved.
            let id = self.ready_rx.recv().map_err(|_| "ready queue closed")?;
            let task = match self.tasks.get_mut(&id) { Some(task) => task, None => continue };
            task.wake.queued.store(false, Ordering::Release);
            let waker = Waker::from(Arc::clone(&task.wake));
            let mut context = Context::from_waker(&waker);
            if let Poll::Ready(result) = task.future.as_mut().poll(&mut context) {
                results.insert(id, result);
                self.tasks.remove(&id);
            }
        }
        Ok(results)
    }
}

fn run() -> Result<(), String> {
    let mut executor = Executor::new();
    let pending_count = Arc::new(AtomicUsize::new(0));
    let mut producers = Vec::new();
    let specs = [(1, Some(21)), (2, Some(7)), (3, None)];
    for (id, input) in specs {
        let event = Arc::new(Event::new());
        let (started_tx, started_rx) = mpsc::sync_channel(1);
        let wait = WaitEvent { event: Arc::clone(&event), first_pending: Some(started_tx), pending_count: Arc::clone(&pending_count) };
        executor.spawn(id, async move { checked_double(wait.await?) })?;
